/**
 * Hand-authored type declaration for the compiled Emscripten output
 * (`halyard-libgit2.js`, regenerated by `build/build.sh` — see BUILD.md).
 * Covers the SHIPPED glue only: `halyard-libgit2.node.js` beside it is the
 * NODEFS-enabled test build, which `tests/libgit2/` loads through
 * `createRequire` rather than a typed ES import.
 * Not compiler output itself; this file is NOT overwritten by a rebuild, so
 * it is safe to hand-edit if the exported shape ever changes (it hasn't
 * since Phase 2: `-sMODULARIZE=1 -sEXPORT_NAME=HalyardLibgit2`).
 *
 * Lets `src/git/libgit2/loader.ts` do a real ES `import` of the compiled
 * `.js` glue (so esbuild bundles it directly into the plugin's `main.js`)
 * while `tsc` type-checks against this declaration instead of needing
 * `allowJs`. TypeScript's "Bundler" module resolution (see tsconfig.json)
 * resolves a `"./halyard-libgit2.js"` specifier against a same-directory
 * `halyard-libgit2.d.ts` first; esbuild separately resolves the same
 * specifier straight to the real `.js` file on disk at bundle time. Both
 * paths were exercised (`npx tsc --noEmit` and the real esbuild bundle) —
 * see this repo's phase notes.
 */

import type { NativeModuleFactory } from "../../native-module";

declare const HalyardLibgit2Factory: NativeModuleFactory;

export default HalyardLibgit2Factory;
